output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts may not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "If a shopper parks a cart at the mouth of a single-file aisle, they must return and retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "return_from_handcarry_aisle",
    "text": "A shopper who enters a single-file shelf aisle without the cart must later return to the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryInSingleFile": {
          "and": [
            "singleFileShelfAisle",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "handCarryInSingleFile",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_wandering_without_cart",
    "text": "After taking a cart, being without it is only acceptable in the cart bay, at an aisle mouth, or inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "entranceCartZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        },
        "permittedNoCartZone": {
          "or": [
            "entranceCartZone",
            "upperAisleMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "permittedNoCartZone"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_needs_cart",
    "text": "Shelf interactions from cart-accessible aisles must be done with the cart; only single-file shelf aisles are hand-carry exceptions.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfFront",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_no_sideways",
    "text": "Inside a single-file shelf aisle, shoppers should move only along the aisle rather than sideways between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        },
        "sidewaysMove": {
          "or": [
            "E",
            "W"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "sidewaysMove"
        ]
      }
    }
  },
  {
    "id": "take_cart_from_bay",
    "text": "A shopper who reaches the cart bay must take a cart before continuing through the store.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "cartBay",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "hasCart"
    }
  }
]
